style.css:
/* Hide YouTube’s default logo */
ytd-topbar-logo-renderer svg {
  display: none !important;
}

/* Smaller FNF Sonic GIF */
ytd-topbar-logo-renderer {
  width: 40px !important;    /* Smaller width */
  height: 40px !important;   /* Smaller height */

  background-image: url("https://media.tenor.com/ljZakkKMSiAAAAAi/fnf-sonic.gif");
  background-repeat: no-repeat;
  background-position: center;
  background-size: contain;

  background-color: transparent !important;
  image-rendering: pixelated;
  transition: transform 0.2s ease;
}

/* Optional hover bounce */
ytd-topbar-logo-renderer:hover {
  animation: sonicBounce 0.4s infinite alternate;
}

@keyframes sonicBounce {
  from { transform: translateY(0); }
  to   { transform: translateY(-5px); }
}
